import{_ as d,C as t,o as n,c as s,j as a,a as h,E as r,a2 as l}from"./chunks/framework.B-bxTAy7.js";const P=JSON.parse('{"title":"数字电路 · 课程主页","description":"数字电路独立课程：数制与编码、逻辑代数与卡诺图、门电路、组合逻辑、触发器、计数器、存储器与 PLD、AD/DA 接口、Verilog 与 FPGA 入门，9 节正文配交互演示。","frontmatter":{"title":"数字电路 · 课程主页","description":"数字电路独立课程：数制与编码、逻辑代数与卡诺图、门电路、组合逻辑、触发器、计数器、存储器与 PLD、AD/DA 接口、Verilog 与 FPGA 入门，9 节正文配交互演示。"},"headers":[],"relativePath":"digital/index.md","filePath":"digital/index.md","lastUpdated":1792416913000}'),c={name:"digital/index.md"};function g(_,e,u,p,f,m){const o=t("Meta"),i=t("CourseRoadmap");return n(),s("div",null,[e[0]||(e[0]=a("h1",{id:"数字电路",tabindex:"-1"},[h("数字电路 "),a("a",{class:"header-anchor",href:"#数字电路","aria-label":'Permalink to "数字电路"'},"​")],-1)),r(o,{time:"5 min",level:"指南",note:"从数制到可编程逻辑，按「能动手验证」的方式重学一遍"}),e[1]||(e[1]=l('<p>数字电路研究「只用 0 和 1 能算出什么、怎么算」。它和<a href="./../ee/">电工学</a>是两条线：电工学讲连续量的电压电流，数电讲离散量的逻辑与状态。两者在多处交叉——<a href="./../ee/08-electronics/rectifier">整流滤波</a>之后接 ADC，就把模拟世界交给了数电；继电控制里的自锁，其实就是最简单的状态保持。</p><p>本课程按新课从零写，不假设先修：每章都配可交互演示，能自己拖、自己验证。</p><h2 id="学完能得到什么" tabindex="-1">学完能得到什么 <a class="header-anchor" href="#学完能得到什么" aria-label="Permalink to &quot;学完能得到什么&quot;">​</a></h2><ul><li>在二进制、十六进制、BCD、补码之间自由换算，并知道补码为什么能统一加减法；</li><li>用布尔代数和卡诺图化简逻辑函数，能从真值表直接写出最简与或式；</li><li>说清 TTL / CMOS 的差别，知道 CMOS 输入为什么不能悬空、三态门为什么能接总线；</li><li>设计译码器、数据选择器、加法器，读懂 74 系列器件的引脚与使能；</li><li>用 D/JK 触发器搭计数器与寄存器，分析时序图的建立/保持与计数模值；</li><li>把数字系统与模拟世界接起来：采样定理、DAC/ADC 结构、PWM 调制；</li><li>把纸面逻辑落成真实硬件：读得懂 Verilog 的 <code>module</code> / <code>assign</code> / <code>always @(posedge clk)</code>，知道 FPGA 的综合、布局布线与时序约束各自在管什么。</li></ul><h2 id="章节路线" tabindex="-1">章节路线 <a class="header-anchor" href="#章节路线" aria-label="Permalink to &quot;章节路线&quot;">​</a></h2>',5)),r(i,{course:"digital"}),e[2]||(e[2]=l('<h2 id="学习路径" tabindex="-1">学习路径 <a class="header-anchor" href="#学习路径" aria-label="Permalink to &quot;学习路径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路径</th><th>顺序</th><th>适合谁</th></tr></thead><tbody><tr><td><strong>速通</strong>（约 4 h）</td><td>01 → 02 → 04 → 05 → 06</td><td>只求会做题、能看懂电路</td></tr><tr><td><strong>系统</strong>（约 6 h）</td><td>01 → 09 顺序读，每章做演示；09 读到「开发流程」一节可先停</td><td>第一次学</td></tr><tr><td><strong>补强</strong></td><td>卡在化简就回 02，卡在时序就回 05 → 06</td><td>学过但分析题不稳</td></tr><tr><td><strong>落地</strong>（约 1.5 h）</td><td>04 → 05 → 06 → 09</td><td>已经会做题，想把逻辑写成代码、上板子跑</td></tr></tbody></table><h2 id="和电工学的关系" tabindex="-1">和电工学的关系 <a class="header-anchor" href="#和电工学的关系" aria-label="Permalink to &quot;和电工学的关系&quot;">​</a></h2><ul><li>数电不需要电路分析基础，但<strong>学了会更顺</strong>：理解「为什么 CMOS 输入不能悬空」要用一点电位概念。</li><li><a href="./../ee/07-control/relay">继电接触器控制</a>里的自锁/互锁，已经是「状态保持」的思想，和触发器一脉相承。</li><li><a href="./../ee/07-control/plc">PLC 与梯形图</a>的扫描周期，是数字系统「时序」观念的工业版。</li><li>更细的器件机理在<a href="./../analog/">模拟电子</a>；这里只关心逻辑行为，不纠结管子的偏置。</li></ul><h2 id="第-09-章在整门课里的位置" tabindex="-1">第 09 章在整门课里的位置 <a class="header-anchor" href="#第-09-章在整门课里的位置" aria-label="Permalink to &quot;第 09 章在整门课里的位置&quot;">​</a></h2><p>前八章把「逻辑关系」讲完了：卡诺图给出最简式，触发器给出特性方程，计数器给出模值与分频比。09 章回答的是另一个问题——<strong>这些纸面结论怎么变成一块真芯片里同时运转的硬件</strong>。</p><ul><li>它<strong>不是</strong>简单地把前八章翻译成代码：同一句加法，函数式写法综合出来是组合逻辑，<code>always @(posedge clk)</code> 里写才是每拍执行一次的寄存器；</li><li>它给出了一条新的主线：<strong>综合 → 布局布线 → 时序约束 → 下载</strong>，以及「为什么我的设计跑不到 100 MHz」；</li><li>它把 04/05/06/07 章各挑了一个代表（译码器、D 触发器、计数器、存储器）写成完整代码，用一张对照表把两边钉在一起；</li><li>学它<strong>不要求</strong>先有编程基础，但要能接受「你在描述电路，不是在叙述步骤」。</li></ul><h2 id="接下来" tabindex="-1">接下来 <a class="header-anchor" href="#接下来" aria-label="Permalink to &quot;接下来&quot;">​</a></h2><ul><li>想先看器件级细节：<a href="./../analog/semiconductor">模拟电子 · 半导体器件</a></li><li>想把这套逻辑用到真实芯片上：<a href="./../embedded/">嵌入式开发</a>（单片机的顺序执行视角，正好和 09 章的并行硬件视角互补）</li><li>想对照舵机的真实数值：<a href="./../embedded/13-servo-control">13 · 舵机控制</a> 与 <a href="./09-verilog-fpga">09 章 · 工程实例</a> 的最后一段</li><li>想确认每章写到什么程度：<a href="./../guide/status">内容状态与成熟度</a></li></ul>',9))])}const x=d(c,[["render",g]]);export{P as __pageData,x as default};
